BEGIN;
CREATE TABLE payment.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, provider_id uuid NOT NULL REFERENCES core.providers(id), external_id text, user_id uuid REFERENCES identity.users(id), amount numeric(20,8) NOT NULL CHECK(amount>0), currency char(3) NOT NULL, status payment.payment_status NOT NULL DEFAULT 'CREATED', idempotency_key text NOT NULL, ledger_transaction_id uuid REFERENCES ledger.transactions(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,idempotency_key), UNIQUE(provider_id,external_id));
CREATE TABLE payment.refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, payment_id uuid NOT NULL REFERENCES payment.payments(id), external_id text, amount numeric(20,8) NOT NULL CHECK(amount>0), ledger_transaction_id uuid REFERENCES ledger.transactions(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment.chargebacks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, payment_id uuid NOT NULL REFERENCES payment.payments(id), external_id text, amount numeric(20,8) NOT NULL CHECK(amount>0), status text NOT NULL, ledger_transaction_id uuid REFERENCES ledger.transactions(id), created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
